using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace Delta.ECS.Generators;

/// <summary>
/// Generates generic structural-operation façades only for the Add/Remove/Create
/// shapes used by a consumer assembly.
/// </summary>
[Generator]
public sealed class GeneratedStructuralGenerator : IIncrementalGenerator
{
    private const int MaxArity = 256;
    private const string Header = """
        // <auto-generated />
        #nullable enable
        namespace Delta.ECS
        {

        """;

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        context.RegisterSourceOutput(
            context.CompilationProvider,
            static (productionContext, compilation) => Execute(compilation, productionContext));
    }

    private static void Execute(Compilation compilation, SourceProductionContext context)
    {
        var shapes = new Dictionary<string, StructuralShape>(StringComparer.Ordinal);
        foreach (SyntaxTree tree in compilation.SyntaxTrees)
        {
            SemanticModel model = compilation.GetSemanticModel(tree);
            foreach (InvocationExpressionSyntax invocation in tree.GetRoot().DescendantNodes().OfType<InvocationExpressionSyntax>())
            {
                if (!TryReadShape(model, invocation, out StructuralShape? shape)
                    || shape is null)
                {
                    continue;
                }

                if (!shapes.ContainsKey(shape.Key))
                {
                    shapes.Add(shape.Key, shape);
                }
            }
        }

        foreach (StructuralShape shape in shapes.Values.OrderBy(static value => value.Key, StringComparer.Ordinal))
        {
            context.AddSource(
                "GeneratedStructural_" + StableName(shape.Key) + ".g.cs",
                Render(shape));
        }
    }

    private static bool TryReadShape(
        SemanticModel model,
        InvocationExpressionSyntax invocation,
        out StructuralShape? shape)
    {
        shape = null;
        if (invocation.Expression is not MemberAccessExpressionSyntax member
            || member.Name is not GenericNameSyntax genericName
            || genericName.Identifier.ValueText is not ("Add" or "Remove" or "Create"))
        {
            return false;
        }

        int arity = genericName.TypeArgumentList.Arguments.Count;
        if (arity is < 1 or > MaxArity)
        {
            return false;
        }

        Receiver receiver = ReadReceiver(model.GetTypeInfo(member.Expression).Type);
        if (receiver == Receiver.None)
        {
            return false;
        }

        if (genericName.Identifier.ValueText == "Create")
        {
            if (receiver != Receiver.World
                || invocation.ArgumentList.Arguments.Count != 1
                || !IsInt32(model.GetTypeInfo(invocation.ArgumentList.Arguments[0].Expression).Type))
            {
                return false;
            }

            shape = new StructuralShape(receiver, StructuralMode.Create, false, arity);
            return true;
        }

        StructuralMode mode;
        if (receiver == Receiver.World)
        {
            if (invocation.ArgumentList.Arguments.Count != 1)
            {
                return false;
            }

            ArgumentSyntax argument = invocation.ArgumentList.Arguments[0];
            if (argument.RefKindKeyword.IsKind(Microsoft.CodeAnalysis.CSharp.SyntaxKind.InKeyword)
                && IsNamedType(model.GetTypeInfo(argument.Expression).Type, "Query"))
            {
                mode = StructuralMode.Query;
            }
            else if (IsEntityBatch(model.GetTypeInfo(argument.Expression).Type))
            {
                mode = StructuralMode.Entities;
            }
            else
            {
                return false;
            }
        }
        else
        {
            if (invocation.ArgumentList.Arguments.Count != 0)
            {
                return false;
            }

            mode = StructuralMode.Sequence;
        }

        shape = new StructuralShape(
            receiver,
            mode,
            genericName.Identifier.ValueText == "Add",
            arity);
        return true;
    }

    private static Receiver ReadReceiver(ITypeSymbol? type)
    {
        string name = type?.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat) ?? string.Empty;
        return name switch
        {
            "global::Delta.ECS.World" => Receiver.World,
            "global::Delta.ECS.EntitySequence" => Receiver.EntitySequence,
            "global::Delta.ECS.FilteredEntitySequence" => Receiver.FilteredEntitySequence,
            _ => Receiver.None
        };
    }

    private static bool IsNamedType(ITypeSymbol? type, string name)
        => type is INamedTypeSymbol named
            && named.Name == name
            && named.ContainingNamespace.ToDisplayString() == "Delta.ECS";

    private static bool IsInt32(ITypeSymbol? type)
        => type?.SpecialType == SpecialType.System_Int32;

    private static bool IsEntityBatch(ITypeSymbol? type)
    {
        if (type is IArrayTypeSymbol array)
        {
            return IsNamedType(array.ElementType, "Entity");
        }

        if (type is not INamedTypeSymbol named
            || named.TypeArguments.Length != 1
            || !IsNamedType(named.TypeArguments[0], "Entity"))
        {
            return false;
        }

        return named.Name is "Span" or "ReadOnlySpan"
            && named.ContainingNamespace.ToDisplayString() == "System";
    }

    private static string Render(StructuralShape shape)
    {
        var source = new StringBuilder(8 * 1024);
        source.Append(Header);
        source.Append("public static class GeneratedStructuralExtensions_")
            .Append(StableName(shape.Key))
            .AppendLine();
        source.AppendLine("{");
        source.AppendLine("    [global::System.Runtime.CompilerServices.MethodImpl(global::System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]");
        source.Append("    public static ")
            .Append(shape.Mode == StructuralMode.Create ? "int Create" : shape.IsAdd ? "int Add" : "int Remove");
        source.Append('<').Append(GenericTypes(shape.Arity)).Append('>');
        source.Append("(this ").Append(ReceiverType(shape.Receiver)).Append(" target");
        switch (shape.Mode)
        {
            case StructuralMode.Entities:
                source.Append(", global::System.ReadOnlySpan<Entity> entities");
                break;
            case StructuralMode.Query:
                source.Append(", in Query query");
                break;
            case StructuralMode.Create:
                source.Append(", int count");
                break;
        }

        source.AppendLine(")");
        source.AppendLine("    {");
        if (shape.Mode == StructuralMode.Create)
        {
            source.Append("        global::System.Span<ComponentId> components = stackalloc ComponentId[")
                .Append(shape.Arity)
                .AppendLine("];");
            AppendPrimaryAssignments(source, "target.Layouts", "components", shape.Arity, "        ");
            source.AppendLine("        var archetype = target.GetOrCreateArchetype(components);");
            source.AppendLine("        return target.Create(archetype, count);");
        }
        else if (shape.Mode == StructuralMode.Sequence)
        {
            source.Append("        global::System.Span<ComponentId> components = stackalloc ComponentId[")
                .Append(shape.Arity)
                .AppendLine("];");
            AppendPrimaryAssignments(source, "target.GeneratedWorld.Layouts", "components", shape.Arity, "        ");
            source.Append("        return target.").Append(shape.IsAdd ? "Add" : "Remove").AppendLine("(components);");
        }
        else
        {
            source.Append("        global::System.Span<ComponentId> components = stackalloc ComponentId[")
                .Append(shape.Arity)
                .AppendLine("];");
            AppendPrimaryAssignments(source, "target.Layouts", "components", shape.Arity, "        ");
            source.Append("        return target.").Append(shape.IsAdd ? "Add" : "Remove");
            if (shape.Mode == StructuralMode.Query)
            {
                source.AppendLine("(in query, components);");
            }
            else
            {
                source.AppendLine("(components, entities);");
            }
        }

        source.AppendLine("    }");
        source.AppendLine("}");
        source.AppendLine("}");
        return GeneratedSourceFormatter.Format(source.ToString());
    }

    private static void AppendPrimaryAssignments(
        StringBuilder source,
        string registry,
        string destination,
        int arity,
        string indent)
    {
        for (int index = 0; index < arity; index++)
        {
            source.Append(indent)
                .Append(destination)
                .Append('[')
                .Append(index)
                .Append("] = ")
                .Append(registry)
                .Append(".GetPrimary<T")
                .Append(index + 1)
                .AppendLine(">();");
        }
    }

    private static string ReceiverType(Receiver receiver)
        => receiver switch
        {
            Receiver.World => "World",
            Receiver.EntitySequence => "EntitySequence",
            Receiver.FilteredEntitySequence => "FilteredEntitySequence",
            _ => string.Empty
        };

    private static string GenericTypes(int arity)
    {
        var values = new string[arity];
        for (int index = 0; index < arity; index++)
        {
            values[index] = "T" + (index + 1).ToString(CultureInfo.InvariantCulture);
        }

        return string.Join(", ", values);
    }

    private static string StableName(string value)
    {
        unchecked
        {
            uint hash = 2166136261;
            foreach (char character in value)
            {
                hash = (hash ^ character) * 16777619;
            }

            return hash.ToString("X8", CultureInfo.InvariantCulture);
        }
    }

    private enum Receiver
    {
        None,
        World,
        EntitySequence,
        FilteredEntitySequence
    }

    private enum StructuralMode
    {
        Entities,
        Query,
        Sequence,
        Create
    }

    private sealed class StructuralShape
    {
        internal StructuralShape(Receiver receiver, StructuralMode mode, bool isAdd, int arity)
        {
            Receiver = receiver;
            Mode = mode;
            IsAdd = isAdd;
            Arity = arity;
        }

        internal Receiver Receiver { get; }
        internal StructuralMode Mode { get; }
        internal bool IsAdd { get; }
        internal int Arity { get; }
        internal string Key => $"{Receiver}|{Mode}|{IsAdd}|{Arity}";
    }
}
